from qiskit import QuantumCircuit, QuantumRegister


def _as_int(value, name):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(name + ' must be an integer')
    return value


def build_circuit(instance):
    """Bell-like basis generator U = CNOT-fanout(f) * (H^{(x)m} (x) I).

    instance keys:
      n: total qubits (2..12)
      m: number of Hadamard control qubits (1 <= m <= n-1)
      f_matrix (optional): (n-m) x m 0/1 matrix; target j is XORed with the
        parity of controls i having f_matrix[j][i] == 1. Default: every target
        receives the parity of all controls (eq_4 for n=3, m=2).
    Layout: qubits 0..m-1 are controls c, qubits m..n-1 are targets t.
    """
    if not isinstance(instance, dict):
        raise ValueError('instance must be a dict')
    n = _as_int(instance.get('n'), 'n')
    m = _as_int(instance.get('m'), 'm')
    if n < 2 or n > 12:
        raise ValueError('n must be in [2, 12]')
    if m < 1 or m > n - 1:
        raise ValueError('m must satisfy 1 <= m <= n-1')
    k = n - m
    mat = instance.get('f_matrix')
    if mat is None:
        mat = [[1] * m for _ in range(k)]
    if not isinstance(mat, (list, tuple)) or len(mat) != k:
        raise ValueError('f_matrix must have n-m rows')
    clean = []
    for row in mat:
        if not isinstance(row, (list, tuple)) or len(row) != m:
            raise ValueError('each f_matrix row must have m entries')
        r = []
        for e in row:
            e = _as_int(e, 'f_matrix entry')
            if e not in (0, 1):
                raise ValueError('f_matrix entries must be 0 or 1')
            r.append(e)
        clean.append(r)
    c = QuantumRegister(m, 'c')
    t = QuantumRegister(k, 't')
    qc = QuantumCircuit(c, t)
    # H on control qubits: H^{(x)m}|a> = 2^{-m/2} sum_c (-1)^{a.c}|c>
    for i in range(m):
        qc.h(c[i])
    # CNOT fan-out implementing |c>|y> -> |c>|y xor f(c)>
    for j in range(k):
        for i in range(m):
            if clean[j][i]:
                qc.cx(c[i], t[j])
    return qc

from qiskit import QuantumCircuit, QuantumRegister


def _as_int(value, name):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(name + ' must be an integer')
    return value


def build_circuit(instance):
    """Bell-like basis generator W = (controlled-X layer) * (H on m controls).

    instance keys: n (total qubits, 2..12), m (1<=m<n, Hadamard controls),
    variant ('xor' or 'and').
    Qubits 0..m-1 are controls c1..cm; qubits m..n-1 are targets.
    """
    if not isinstance(instance, dict):
        raise ValueError('instance must be a dict')
    n = _as_int(instance.get('n', 3), 'n')
    m = _as_int(instance.get('m', 2), 'm')
    variant = instance.get('variant', 'xor')
    if n < 2 or n > 12:
        raise ValueError('n must be in 2..12')
    if m < 1 or m >= n:
        raise ValueError('m must satisfy 1 <= m < n')
    if variant not in ('xor', 'and'):
        raise ValueError("variant must be 'xor' or 'and'")
    c = QuantumRegister(m, 'c')
    t = QuantumRegister(n - m, 't')
    qc = QuantumCircuit(c, t)
    # eq_2 right factor: H on the m control qubits
    for i in range(m):
        qc.h(c[i])
    # eq_2 left factor: sum_c |c><c| (x) X^{f(c)} on each target
    for tq in t:
        if variant == 'xor':
            # eq_4 f_A: CNOT fan-out, target gets parity of controls
            for cq in c:
                qc.cx(cq, tq)
        else:
            # eq_4 f_B / eq_5: multi-controlled X, target flips iff all controls are 1
            if m == 1:
                qc.cx(c[0], tq)
            else:
                qc.mcx(list(c), tq)
    return qc

from qiskit import QuantumCircuit, QuantumRegister


def _int(v, name):
    if isinstance(v, bool) or not isinstance(v, int):
        raise ValueError(name + " must be an integer")
    return v


def build_circuit(instance):
    """Return V = CNOT_A (H^m (x) I). Qubits 0..m-1 are sup, qubits m..n-1 are tgt."""
    if not isinstance(instance, dict):
        raise ValueError("instance must be a dict")
    if "n" not in instance or "m" not in instance or "A" not in instance:
        raise ValueError("instance needs n, m, A")
    n = _int(instance["n"], "n")
    m = _int(instance["m"], "m")
    if m < 1 or n < m + 1 or n > 12:
        raise ValueError("require 1 <= m, m+1 <= n <= 12")
    k = n - m
    A = instance["A"]
    if not isinstance(A, (list, tuple)) or len(A) != k:
        raise ValueError("A must have n-m rows")
    rows = []
    for r in A:
        if not isinstance(r, (list, tuple)) or len(r) != m:
            raise ValueError("each row of A must have m entries")
        row = []
        for e in r:
            if isinstance(e, bool):
                e = int(e)
            if not isinstance(e, int) or e not in (0, 1):
                raise ValueError("A entries must be 0 or 1")
            row.append(e)
        rows.append(row)
    sup = QuantumRegister(m, "sup")
    tgt = QuantumRegister(k, "tgt")
    qc = QuantumCircuit(sup, tgt)
    # eq_3/eq_1: H on |s> gives sum_x (-1)^{s.x}|x>
    for j in range(m):
        qc.h(sup[j])
    # eq_3/eq_1: CNOT_A maps |x>|t> to |x>|Ax xor t>
    for i in range(k):
        for j in range(m):
            if rows[i][j] == 1:
                qc.cx(sup[j], tgt[i])
    return qc
